        conventional-commit messages, grouped into Breaking Changes,
        Features, and Bug Fixes sections (only sections with content are
        included).
    #>
    param(
        [Parameter(Mandatory)]
        [string] $Version,

        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [string[]] $CommitMessages,

